param([Parameter(Mandatory)][ValidateSet('LocalReader','GameBubUsb')][string]$Mode,[Parameter(Mandatory)][string]$Volume,[Parameter(Mandatory)][string]$FixtureRoot)
$ErrorActionPreference='Stop';$drive=(Get-Volume -DriveLetter $Volume.TrimEnd(':') -ErrorAction Stop);if($drive.FileSystem -ne 'FAT32'){throw "Expected FAT32, found $($drive.FileSystem)"};if($drive.FileSystemLabel -eq 'GAME BUB'){throw 'Refusing virtual UF2 update drive'}
$fixture=(Resolve-Path $FixtureRoot).Path;$sentinel=Join-Path $fixture '.GBTEST-SENTINEL';if(!(Test-Path -LiteralPath $sentinel)){throw 'Fixture sentinel missing'}
$run=(Get-Content $sentinel|Where-Object{$_ -like 'run=*'}).Substring(4);$destination=Join-Path ($Volume.TrimEnd(':')+':\') "GBTEST/$run";if(Test-Path -LiteralPath $destination){throw "Refusing existing destination $destination"}
Copy-Item -LiteralPath $fixture -Destination $destination -Recurse;Get-ChildItem $fixture -Recurse -File|ForEach-Object{$relative=$_.FullName.Substring($fixture.Length+1);$copy=Join-Path $destination $relative;$a=(Get-FileHash $_ -Algorithm SHA256).Hash;$b=(Get-FileHash $copy -Algorithm SHA256).Hash;if($a-ne$b){throw "Hash mismatch $relative"}};Write-Output "SD_EXPLORER_COPY_PASS mode=$Mode volume=$Volume destination=$destination"
